using NUnit.Framework;

namespace Depths.Tests
{
    /// <summary>
    /// Brunch packs moving, against the running game: rows recorded by tools/brunch-move-parity.js on
    /// 2026-10-06 from the game's own tickBodies(). A pack walling a shooter, a pack with nothing to
    /// guard chasing and spending itself on the player, and the B and A+ guard variants. Every 10th
    /// tick, per body in spawn order: x, y, vx, vy, curSpeed, hp, or dead; then the player's hp.
    /// </summary>
    [TestFixture]
    public sealed class BrunchMoveParityTests
    {
        static void Check(string variant, double[] player,
                          (BodyKind kind, double x, double y, int? packId, int slot, double curSpeed, int idleTimer, double shootCd)[] bodies,
                          int ticks, int jitterDraws, int runDraws, object[][] rows)
        {
            string saved = Balance.BrunchVariant;
            try
            {
                Balance.BrunchVariant = variant;
                var run = new RunState(new Rng(4242)) { dungeon = Dungeon.FromSeed(new Rng(4242)) };
                run.state = "playing";
                var p = run.player;
                p.x = p.lagX = player[0]; p.y = p.lagY = player[1];
                p.hp = p.maxHp = 1e6;
                TickOrder.HitboxX = p.lagX; TickOrder.HitboxY = p.lagY;
                var placed = new System.Collections.Generic.List<Enemy>();
                foreach (var b in bodies)
                {
                    var e = Enemy.Of(b.kind, b.x, b.y);
                    e.noticeTimer = 0; e.aggroTimer = 0; e.packId = b.packId; e.packSlot = b.slot;
                    e.curSpeed = b.curSpeed; e.idleTimer = b.idleTimer; e.shootCd = b.shootCd;
                    run.enemies.Add(e); placed.Add(e);
                }
                int j0 = run.rng.JitterCalls, r0 = run.rng.RunCalls, row = 0;
                for (int t = 1; t <= ticks; t++)
                {
                    p.iframes = 0;
                    TickOrder.TickBodies(run);
                    if (t % 10 != 0) continue;
                    var want = rows[row++];
                    Assert.That(t, Is.EqualTo(System.Convert.ToInt32(want[0])));
                    for (int i = 0; i < placed.Count; i++)
                    {
                        var e = placed[i];
                        int o = 1 + i * 6;
                        string at = " (body " + i + ", tick " + t + ")";
                        if (want[o] is string) { Assert.That(run.enemies, Does.Not.Contain(e), "should be dead" + at); continue; }
                        Assert.That(run.enemies, Does.Contain(e), "died early" + at);
                        double D(int k) => System.Convert.ToDouble(want[o + k]);
                        Assert.That(e.x, Is.EqualTo(D(0)).Within(1e-6), "x" + at);
                        Assert.That(e.y, Is.EqualTo(D(1)).Within(1e-6), "y" + at);
                        Assert.That(e.vx, Is.EqualTo(D(2)).Within(1e-6), "vx" + at);
                        Assert.That(e.vy, Is.EqualTo(D(3)).Within(1e-6), "vy" + at);
                        if (e.kind == BodyKind.Brunch) Assert.That(e.curSpeed, Is.EqualTo(D(4)).Within(1e-6), "curSpeed" + at);
                        Assert.That(e.hp, Is.EqualTo(D(5)).Within(1e-6), "hp" + at);
                    }
                    Assert.That(p.hp, Is.EqualTo(System.Convert.ToDouble(want[1 + placed.Count * 6])).Within(1e-6), "player hp at tick " + t);
                }
                Assert.That(run.rng.JitterCalls - j0, Is.EqualTo(jitterDraws), "jitter draws");
                Assert.That(run.rng.RunCalls - r0, Is.EqualTo(runDraws), "run draws (loot)");
            }
            finally { Balance.BrunchVariant = saved; }
        }

